from pathlib import Path

HOME = Path("artifacts/solana-multi-wallet/src/pages/home.tsx")
CSS = Path("artifacts/solana-multi-wallet/src/index.css")

def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f"Could not patch {label}: expected block not found")
    return text.replace(old, new, 1)

home = HOME.read_text()
home = replace_once(home, "const WITHDRAWAL_STORAGE_KEY = 'multi-wallet:withdrawal-address:v1';\n", "const WITHDRAWAL_STORAGE_KEY = 'multi-wallet:withdrawal-address:v1';\nconst THEME_STORAGE_KEY = 'multi-wallet:theme:v1';\n", 'theme storage key')
home = replace_once(home, '  const [tokenInput, setTokenInput] = useState(token);\n  const [unlocked, setUnlocked] = useState(Boolean(token));\n\n  const [wallets, setWallets] = useState<WalletRow[]>([]);\n', "  const [tokenInput, setTokenInput] = useState(token);\n  const [unlocked, setUnlocked] = useState(Boolean(token));\n  const [theme, setTheme] = useState<'light' | 'dark'>(() => {\n    const saved = localStorage.getItem(THEME_STORAGE_KEY);\n    return saved === 'dark' ? 'dark' : 'light';\n  });\n\n  const [wallets, setWallets] = useState<WalletRow[]>([]);\n", 'theme state')
home = replace_once(home, '  useEffect(() => {\n    if (!unlocked) return;\n    void refresh();\n', '  useEffect(() => {\n    document.documentElement.dataset.theme = theme;\n    localStorage.setItem(THEME_STORAGE_KEY, theme);\n  }, [theme]);\n\n  useEffect(() => {\n    if (!unlocked) return;\n    void refresh();\n', 'theme effect')
home = replace_once(home, '          <h1>24/7 EXECUTION</h1>\n          <p>\n', '          <div className="title-with-theme">\n            <h1>24/7 EXECUTION</h1>\n            <button\n            className={`theme-toggle ${theme === \'dark\' ? \'on\' : \'\'}`}\n            onClick={() =>\n              setTheme((current) =>\n                current === \'dark\' ? \'light\' : \'dark\',\n              )\n            }\n            aria-label={\n              theme === \'dark\'\n                ? \'Switch to light mode\'\n                : \'Switch to dark mode\'\n            }\n            aria-pressed={theme === \'dark\'}\n            title={theme === \'dark\' ? \'Light mode\' : \'Dark mode\'}\n          >\n            <span />\n          </button>\n          </div>\n          <p>\n', 'unlock theme toggle')
home = replace_once(home, '        <header className="topbar">\n          <h1>24/7 EXECUTION</h1>\n          <div className="topbar-actions">\n', '        <header className="topbar">\n          <div className="title-with-theme">\n            <h1>24/7 EXECUTION</h1>\n            <button\n            className={`theme-toggle ${theme === \'dark\' ? \'on\' : \'\'}`}\n            onClick={() =>\n              setTheme((current) =>\n                current === \'dark\' ? \'light\' : \'dark\',\n              )\n            }\n            aria-label={\n              theme === \'dark\'\n                ? \'Switch to light mode\'\n                : \'Switch to dark mode\'\n            }\n            aria-pressed={theme === \'dark\'}\n            title={theme === \'dark\' ? \'Light mode\' : \'Dark mode\'}\n          >\n            <span />\n          </button>\n          </div>\n          <div className="topbar-actions">\n', 'header theme toggle')
HOME.write_text(home)
css = CSS.read_text()
css += "\n\n/* v6.6 compact black/white theme toggle */\n.title-with-theme {\n  display:flex;\n  align-items:center;\n  gap:9px;\n  min-width:0;\n}\n\n.theme-toggle {\n  position:relative;\n  width:27px;\n  height:15px;\n  flex:0 0 auto;\n  border:1px solid #cfcfcf;\n  border-radius:999px;\n  background:#f1f1f1;\n  padding:0;\n  transition:background .16s ease, border-color .16s ease;\n}\n\n.theme-toggle span {\n  position:absolute;\n  top:2px;\n  left:2px;\n  width:9px;\n  height:9px;\n  border-radius:50%;\n  background:#111;\n  transition:transform .16s ease, background .16s ease;\n}\n\n.theme-toggle.on {\n  background:#111;\n  border-color:#111;\n}\n\n.theme-toggle.on span {\n  transform:translateX(12px);\n  background:#fff;\n}\n\nhtml[data-theme='dark'],\nhtml[data-theme='dark'] body,\nhtml[data-theme='dark'] #root,\nhtml[data-theme='dark'] .page {\n  background:#000;\n  color:#fff;\n}\n\nhtml[data-theme='dark'] {\n  color-scheme:dark;\n}\n\nhtml[data-theme='dark'] .section,\nhtml[data-theme='dark'] .wallet-row,\nhtml[data-theme='dark'] .notice,\nhtml[data-theme='dark'] .sheet-head {\n  border-color:#262626;\n}\n\nhtml[data-theme='dark'] .muted,\nhtml[data-theme='dark'] .index,\nhtml[data-theme='dark'] .wallet-id span,\nhtml[data-theme='dark'] .status-row,\nhtml[data-theme='dark'] .validation,\nhtml[data-theme='dark'] .global-grid label,\nhtml[data-theme='dark'] .strategy-global label,\nhtml[data-theme='dark'] .note,\nhtml[data-theme='dark'] .footnote,\nhtml[data-theme='dark'] .sheet-head span,\nhtml[data-theme='dark'] .sheet-label-row,\nhtml[data-theme='dark'] .withdraw-amount-row span,\nhtml[data-theme='dark'] .sheet-copy,\nhtml[data-theme='dark'] .sheet-footnote,\nhtml[data-theme='dark'] .delete-note,\nhtml[data-theme='dark'] .empty {\n  color:#8d8d8d;\n}\n\nhtml[data-theme='dark'] input {\n  background:#000;\n  color:#fff;\n  border-color:#303030;\n}\n\nhtml[data-theme='dark'] input::placeholder {\n  color:#6f6f6f;\n}\n\nhtml[data-theme='dark'] input:focus {\n  border-color:#fff;\n}\n\nhtml[data-theme='dark'] .link-button,\nhtml[data-theme='dark'] .top-menu-button,\nhtml[data-theme='dark'] .save,\nhtml[data-theme='dark'] .sheet-label-row button {\n  color:#fff;\n}\n\nhtml[data-theme='dark'] .wallet-tool,\nhtml[data-theme='dark'] .trade-row .sell,\nhtml[data-theme='dark'] .auto,\nhtml[data-theme='dark'] .secondary,\nhtml[data-theme='dark'] .sheet-secondary,\nhtml[data-theme='dark'] .sheet-danger {\n  background:#000;\n  color:#fff;\n  border-color:#444;\n}\n\nhtml[data-theme='dark'] .managed {\n  color:#fff;\n  border-color:#fff;\n}\n\nhtml[data-theme='dark'] .managed.off {\n  color:#777;\n  border-color:#3b3b3b;\n}\n\nhtml[data-theme='dark'] .trade-row .buy,\nhtml[data-theme='dark'] .primary,\nhtml[data-theme='dark'] .sheet-primary,\nhtml[data-theme='dark'] .unlock button {\n  background:#fff;\n  color:#000;\n  border-color:#fff;\n}\n\nhtml[data-theme='dark'] .auto.on {\n  background:#fff;\n  color:#000;\n  border-color:#fff;\n}\n\nhtml[data-theme='dark'] .status-row strong,\nhtml[data-theme='dark'] .validation.valid {\n  color:#fff;\n}\n\nhtml[data-theme='dark'] .row-error,\nhtml[data-theme='dark'] .validation.error,\nhtml[data-theme='dark'] .notice {\n  color:#d28b8b;\n}\n\nhtml[data-theme='dark'] .sheet-overlay {\n  background:rgba(255,255,255,.12);\n}\n\nhtml[data-theme='dark'] .funds-sheet {\n  background:#050505;\n  color:#fff;\n  box-shadow:0 -12px 40px rgba(0,0,0,.55);\n}\n\nhtml[data-theme='dark'] .sheet-handle {\n  background:#4a4a4a;\n}\n\nhtml[data-theme='dark'] .sheet-close {\n  color:#aaa;\n}\n"
CSS.write_text(css)
print("v6.6 dark mode patch applied.")
